/**
 * Drizzle schema barrel. One file per domain lives next to this one and is
 * re-exported here, so drizzle-kit and the typed `db` client see every table.
 *
 * - auth.ts: generated by the Better Auth CLI (`pnpm auth:schema`); don't edit by hand.
 * - test-crud.ts: the Test CRUD reference feature (and its uploaded images).
 * - rbac.ts: roles, role permissions and user roles.
 * - attachments.ts: files stored in Cloudinary, linked to entities.
 * - audit.ts: the audit log of admin actions.
 * - portfolio.ts: the portfolio at `/` and its contact messages (the `portfolio` layer).
 * - apps/<app>.ts: the showcase apps' tables, each row owned by a user (the `apps` layer).
 * - taskline/*.ts: Taskline, the project management app at /app/taskline (the `taskline` layer).
 * - columns.ts: column helpers (localized text), no tables.
 *
 * `pnpm new:feature` adds its table's file above the marker line.
 */

